answer.sql:
SELECT COUNT(DISTINCT p.ID) AS patient_count
FROM Patient AS p
WHERE EXISTS (
    SELECT 1 FROM Laboratory AS l
    WHERE l.ID = p.ID AND l.GLU < 180
)
AND EXISTS (
    SELECT 1 FROM Examination AS e
    WHERE e.ID = p.ID AND e.Thrombosis = 0
);

